#!/usr/bin/env node
// Complete source-text construction only. No Python import, AST or scientific execution.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const args=process.argv.slice(2);
function argument(name) {
  const i=args.indexOf(name);
  if(i<0||!args[i+1])throw Error('Required '+name);
  return path.resolve(args[i+1]);
}
const sourceDirectory=argument('--source-directory');
const generatedDirectory=argument('--generated-directory');
const digest=s=>crypto.createHash('sha256').update(s).digest('hex');
function verify(content,record,label) {
  const bytes=Buffer.byteLength(content,'utf8');
  if(bytes!==record.bytes||digest(content)!==record.sha256)throw Error('Whole source mismatch '+label);
  if(bytes>=100000)throw Error('Complete source must remain below 100000 bytes: '+label);
}
function read(record) {
  const candidates=[path.join(sourceDirectory,record.name),
    path.join(sourceDirectory,record.path),
    path.join(sourceDirectory,record.path.replace(/^topics\/visible-flex-larger-amplitude\//,''))];
  let mismatch=false;
  for(const file of [...new Set(candidates)]) {
    if(!fs.existsSync(file))continue;
    const stat=fs.statSync(file);
    if(stat.size!==record.bytes){mismatch=true;continue;}
    const content=fs.readFileSync(file,'utf8');
    if(digest(content)!==record.sha256){mismatch=true;continue;}
    verify(content,record,file);
    return content;
  }
  throw Error((mismatch?'No exact whole source among candidate paths: ':'Missing whole parent source: ')+record.path);
}
function write(content,record) {
  verify(content,record,record.path);
  fs.mkdirSync(generatedDirectory,{recursive:true});
  const file=path.join(generatedDirectory,record.name);
  if(fs.existsSync(file)&&fs.readFileSync(file,'utf8')!==content)
    throw Error('Existing distinct generated source is preserved: '+file);
  if(!fs.existsSync(file))fs.writeFileSync(file,content,'utf8');
  verify(fs.readFileSync(file,'utf8'),record,file);
}

